mapper.select:
SELECT CAST(b.id AS CHAR) AS id, CAST(sp.id AS CHAR) AS specialistId, u.full_name AS specialistName, sp.avatar_url AS specialistAvatar, b.topic AS serviceName, TIMESTAMP(ts.slot_date, ts.start_time) AS appointmentDateTime, b.status AS status, b.price AS amount FROM bookings b JOIN time_slots ts ON b.slot_id = ts.id JOIN specialist_profiles sp ON b.specialist_id = sp.id JOIN users u ON sp.user_id = u.id WHERE b.customer_id = #{customerId}
AND b.status = #{status}
AND TIMESTAMP(ts.slot_date, ts.start_time) >= #{currentTime} ORDER BY ts.slot_date ASC, ts.start_time ASC
AND TIMESTAMP(ts.slot_date, ts.start_time) < #{currentTime} ORDER BY ts.slot_date DESC, ts.start_time DESC
ORDER BY ts.slot_date DESC, ts.start_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
WHERE b.customer_id = #{customerId}

    AND b.status = #{status}


    AND TIMESTAMP(ts.slot_date, ts.start_time) >= #{currentTime}


    AND TIMESTAMP(ts.slot_date, ts.start_time) < #{currentTime}

SELECT
    COALESCE(COUNT(1), 0) AS totalCompletedAppointments,
    COALESCE(SUM(b.price), 0) AS totalAmountSpent,
    COALESCE(
        SUM(
            TIMESTAMPDIFF(
                MINUTE,
                TIMESTAMP(ts.slot_date, ts.start_time),
                TIMESTAMP(ts.slot_date, ts.end_time)
            )
        ) / 60.0,
        0
    ) AS totalConsultationHours
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

SELECT DISTINCT
    sp.id AS specialistId,
    u.full_name AS specialistName
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
JOIN specialist_profiles sp ON b.specialist_id = sp.id
JOIN users u ON sp.user_id = u.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

ORDER BY sp.id ASC

SELECT
    COALESCE(COUNT(1), 0) AS totalCompletedAppointments,
    COALESCE(SUM(b.price), 0) AS totalAmountSpent,
    COALESCE(
        SUM(
            TIMESTAMPDIFF(
                MINUTE,
                TIMESTAMP(ts.slot_date, ts.start_time),
                TIMESTAMP(ts.slot_date, ts.end_time)
            )
        ) / 60.0,
        0
    ) AS totalConsultationHours
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

SELECT DISTINCT
    sp.id AS specialistId,
    u.full_name AS specialistName
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
JOIN specialist_profiles sp ON b.specialist_id = sp.id
JOIN users u ON sp.user_id = u.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

ORDER BY sp.id ASC

SELECT
    DATE_FORMAT(ts.slot_date, '%m-%d') AS dateLabel,
    COUNT(1) AS count,
    COALESCE(
        SUM(
            TIMESTAMPDIFF(
                MINUTE,
                TIMESTAMP(ts.slot_date, ts.start_time),
                TIMESTAMP(ts.slot_date, ts.end_time)
            )
        ) / 60.0,
        0
    ) AS hours
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

GROUP BY DATE_FORMAT(ts.slot_date, '%Y-%m-%d')
ORDER BY DATE_FORMAT(ts.slot_date, '%Y-%m-%d') ASC

SELECT
    DATE_FORMAT(ts.slot_date, '%Y-%m') AS dateLabel,
    COUNT(1) AS count,
    COALESCE(
        SUM(
            TIMESTAMPDIFF(
                MINUTE,
                TIMESTAMP(ts.slot_date, ts.start_time),
                TIMESTAMP(ts.slot_date, ts.end_time)
            )
        ) / 60.0,
        0
    ) AS hours
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

GROUP BY DATE_FORMAT(ts.slot_date, '%Y-%m')
ORDER BY DATE_FORMAT(ts.slot_date, '%Y-%m') ASC

SELECT ec.category_name AS categoryName, COALESCE(SUM(b.price), 0) AS amount, COUNT(1) AS count FROM bookings b JOIN time_slots ts ON b.slot_id = ts.id JOIN specialist_profiles sp ON b.specialist_id = sp.id JOIN expertise_categories ec ON sp.category_id = ec.id WHERE b.customer_id = #{customerId} AND b.status = #{status}
AND ts.slot_date >= #{startDate}
AND ts.slot_date <= #{endDate}
GROUP BY ec.category_name ORDER BY amount DESC, count DESC

SELECT
    DAYOFWEEK(ts.slot_date) AS dayOfWeek,
    COUNT(1) AS count
FROM bookings b
JOIN time_slots ts ON b.slot_id = ts.id
WHERE b.customer_id = #{customerId}
AND b.status = #{status}

    AND ts.slot_date >= #{startDate}


    AND ts.slot_date <= #{endDate}

GROUP BY DAYOFWEEK(ts.slot_date)
ORDER BY DAYOFWEEK(ts.slot_date) ASC
